package dev.zomboid.gore;
import java.util.*;
public class Render45 {
 static int count;static void ok(boolean b,String s){count++;if(!b)throw new AssertionError(s);}
 public static class Pose {public int depth;public void pushPose(){depth++;}public void popPose(){depth--;}public Object last(){return this;}}
 public static class Part {public boolean visible=true,skipDraw;public List<Object>cubes=new ArrayList<>();public Map<String,Object>children=new HashMap<>();public void translateAndRotate(Object pose){}}
 public static class Consumer {public List<float[]>vertices=new ArrayList<>();public List<Float>uv=new ArrayList<>();public Consumer addVertex(Object p,float x,float y,float z){vertices.add(new float[]{x,y,z});return this;}public Consumer setColor(int color){return this;}public Consumer setUv(float u,float v){uv.add(u);return this;}public Consumer setOverlay(int i){return this;}public Consumer setLight(int i){return this;}public Consumer setNormal(Object p,float x,float y,float z){return this;}}
 public static class Buffer {public Consumer vc=new Consumer();public Object getBuffer(Object type){return vc;}}
 static void cached(Part p,float width){Model25.CUBES.put(p,List.of(new Mesh12.Cube(new Mesh12.Box(-width/2,0,-2,width/2,12,2),List.of())));Model25.LAYOUTS.put(p,new Model25.Layout(System.identityHashCode(p.cubes),System.identityHashCode(p.children),0,p.skipDraw));}
 public static void main(String[]args){for(float width:new float[]{3,4}){Part part=new Part();cached(part,width);Buffer b=new Buffer();Pose pose=new Pose();Player45.Context ctx=new Player45.Context(new int[]{1,255,128,0,1,12000,0},b);ctx.parts=Map.of(part,2);Player45.CURRENT.set(ctx);Player45.draw(part,pose,1234,0);ok(b.vc.vertices.size()==4,"first aid mark is rendered on player model rather than skipped by zombie-only context");for(float[]v:b.vc.vertices)ok(Math.abs(v[0]-(width/32+.018/16))<1e-5&&v[1]>=0&&v[1]<=.75&&v[2]>=-.125&&v[2]<=.125,"mark stays within wide/slim arm bounds");ok(pose.depth==0,"model matrix restored after drawing");ok(b.vc.uv.stream().allMatch(u->u<=.5f),"unbandaged wound uses wound half of atlas");b.vc=new Consumer();ctx.marks[6]=1;Player45.draw(part,pose,1234,0);ok(b.vc.vertices.size()==4&&b.vc.uv.stream().allMatch(u->u>=.5f),"dressing replaces wound with cloth atlas");b.vc=new Consumer();part.visible=false;Player45.draw(part,pose,1234,0);ok(b.vc.vertices.isEmpty(),"hidden parts cannot show floating wound decals");Player45.end();part.visible=true;Player45.draw(part,pose,1234,0);ok(b.vc.vertices.isEmpty(),"healthy next player cannot inherit previous wound context");}System.out.println("WIDE_SLIM_DRESSING_RENDER_SCOPE_CHECKS="+count);}
}
